#!/usr/bin/env bun
/**
 * Tmux Detector — Harness-agnostic fallback adapter for Trail Boss
 *
 * Polls tmux panes for stuck sessions using heuristics (quiet output + prompt detection).
 * Emits normalized events to the daemon's /event/normalized endpoint.
 *
 * Opt-in: Panes are monitored only if their title contains "@tb-" prefix.
 * This ensures explicit consent and avoids false positives from unrelated panes.
 *
 * Detection heuristics:
 * - Quiet period: No output change for STUCK_QUIET_MS (default 30s)
 * - Prompt pattern: Last line ends with a prompt marker (>, $, ?, →, etc.)
 *
 * Usage:
 *   bun run daemon/tmux-detector.ts [--interval-ms 2000] [--quiet-ms 30000]
 */

import { $, shell } from "bun";

// ============================================================================
// Configuration
// ============================================================================

const DAEMON_URL = "http://localhost:4000/event/normalized";
const POLL_INTERVAL_MS = Number(process.env.TB_POLL_INTERVAL_MS) || 2000;
const STUCK_QUIET_MS = Number(process.env.TB_STUCK_QUIET_MS) || 30000; // 30s default
const OPT_IN_PREFIX = "@tb-";

// Prompt patterns that suggest an interactive session waiting for input
const PROMPT_PATTERNS = [
  /[>#$%]\s*$/,           // Shell prompts: >, #, $, %
  /\?\s*$/,               // Question prompts
  /→\s*$/,                // Arrow prompts (CLI tools)
  /:\s*$/,                // Colon prompts (readline-style)
  /\]\s*$/,               // Closing bracket prompts
  />\s*$/,                // Generic > prompts
  /\$\s*$/,               // Generic $ prompts
  /✓\s*$/,               // Checkmark + prompt
  /●\s*$/,               // Bullet + prompt
];

// ============================================================================
// Types
// ============================================================================

interface PaneState {
  paneId: string;
  sessionId: string;      // Synthetic ID from pane title
  lastContent: string;     // Last captured content
  lastChangeTime: number;  // Unix ms when content last changed
  isStuck: boolean;        // Current stuck state
  registered: boolean;     // Whether we've sent a 'registered' event
}

interface DetectorState {
  panes: Map<string, PaneState>;  // key: paneId
  lastPollTime: number;
}

// ============================================================================
// Tmux commands
// ============================================================================

/**
 * List all panes in the tmux server.
 * Returns array of pane IDs that exist.
 */
async function listAllPanes(): Promise<string[]> {
  try {
    const result = await shell`tmux list-panes -a -F '#{pane_id}'`.quiet();
    if (result.exitCode !== 0) {
      console.error("[tmux] list-panes failed:", result.stderr.toString());
      return [];
    }
    const output = result.stdout.toString().trim();
    if (!output) return [];
    return output.split("\n");
  } catch (err) {
    console.error("[tmux] list-panes error:", err);
    return [];
  }
}

/**
 * Get the title of a pane.
 * Used for opt-in detection and synthetic session ID generation.
 */
async function getPaneTitle(paneId: string): Promise<string> {
  try {
    const result = await shell`tmux display -p -t ${paneId} -W '#{pane_title}'`.quiet();
    if (result.exitCode !== 0) return "";
    return result.stdout.toString().trim();
  } catch {
    return "";
  }
}

/**
 * Capture the current content of a pane.
 * Returns the visible text content.
 */
async function capturePane(paneId: string): Promise<string> {
  try {
    // -p for output to stdout, -e for escape sequences
    const result = await shell`tmux capture-pane -p -t ${paneId}`.quiet();
    if (result.exitCode !== 0) return "";
    return result.stdout.toString();
  } catch {
    return "";
  }
}

// ============================================================================
// Detection logic
// ============================================================================

/**
 * Check if a pane has opted in to monitoring.
 * Opt-in is indicated by the presence of OPT_IN_PREFIX in the pane title.
 */
function isOptedIn(title: string): boolean {
  return title.includes(OPT_IN_PREFIX);
}

/**
 * Generate a synthetic session ID from the pane title.
 * Extracts the identifier after @tb- prefix.
 * Falls back to the pane ID if no valid identifier is found.
 */
function generateSessionId(paneId: string, title: string): string {
  const match = title.match(/@tb-([^\s]+)/);
  if (match && match[1]) {
    return `tmux-${match[1]}`;
  }
  return `tmux-pane-${paneId.replace("%", "")}`;
}

/**
 * Check if the last line looks like a prompt.
 * This indicates the session is waiting for user input.
 */
function looksLikePrompt(content: string): boolean {
  const lines = content.trim().split("\n");
  const lastLine = lines[lines.length - 1] || "";
  return PROMPT_PATTERNS.some(pattern => pattern.test(lastLine));
}

/**
 * Check if content has changed since last check.
 */
function hasContentChanged(oldContent: string, newContent: string): boolean {
  // Normalize whitespace to ignore minor formatting differences
  const normalize = (s: string) => s.replace(/\s+/g, " ").trim();
  return normalize(oldContent) !== normalize(newContent);
}

/**
 * Determine if a pane should be considered stuck.
 * A pane is stuck if:
 * - It has been quiet for STUCK_QUIET_MS
 * - The last line looks like a prompt
 */
function shouldBeStuck(state: PaneState, now: number): boolean {
  const quietDuration = now - state.lastChangeTime;
  const isQuiet = quietDuration >= STUCK_QUIET_MS;

  if (!isQuiet) return false;

  // Check if the last content looks like a prompt
  return looksLikePrompt(state.lastContent);
}

// ============================================================================
// Event emission
// ============================================================================

interface NormalizedEvent {
  type: "stuck" | "unstuck" | "registered" | "ended";
  sessionId: string;
  paneId: string;
  cwd?: string;
  transcriptPath?: string;
  reason?: "stopped" | "permission";
  message?: string;
  timestamp: number;
}

/**
 * Emit a normalized event to the daemon.
 */
async function emitEvent(event: NormalizedEvent): Promise<void> {
  try {
    const response = await fetch(DAEMON_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(event),
    });

    if (!response.ok) {
      const error = await response.text();
      console.error(`[emit] failed: ${response.status} ${error}`);
    } else {
      console.log(`[emit] ${event.type}: ${event.sessionId.slice(0, 16)}...`);
    }
  } catch (err) {
    console.error(`[emit] error:`, err);
  }
}

/**
 * Emit a stuck event.
 */
async function emitStuck(state: PaneState): Promise<void> {
  await emitEvent({
    type: "stuck",
    sessionId: state.sessionId,
    paneId: state.paneId,
    cwd: "", // Unknown for tmux-only detection
    transcriptPath: "",
    reason: "stopped", // Default - we can't distinguish permission vs stopped
    message: "[tmux-detector] Quiet at prompt",
    timestamp: Date.now(),
  });
}

/**
 * Emit an unstuck event.
 */
async function emitUnstuck(state: PaneState): Promise<void> {
  await emitEvent({
    type: "unstuck",
    sessionId: state.sessionId,
    paneId: state.paneId,
    timestamp: Date.now(),
  });
}

/**
 * Emit a registered event.
 */
async function emitRegistered(state: PaneState): Promise<void> {
  await emitEvent({
    type: "registered",
    sessionId: state.sessionId,
    paneId: state.paneId,
    cwd: "",
    transcriptPath: "",
    timestamp: Date.now(),
  });
}

/**
 * Emit an ended event.
 */
async function emitEnded(state: PaneState): Promise<void> {
  await emitEvent({
    type: "ended",
    sessionId: state.sessionId,
    timestamp: Date.now(),
  });
}

// ============================================================================
// Main detection loop
// ============================================================================

async function poll(state: DetectorState): Promise<void> {
  const now = Date.now();
  state.lastPollTime = now;

  // Get all current panes
  const allPanes = await listAllPanes();
  const currentPaneSet = new Set(allPanes);

  // Check each known pane
  for (const [paneId, paneState] of state.panes) {
    // Pane no longer exists
    if (!currentPaneSet.has(paneId)) {
      console.log(`[poll] pane ended: ${paneId}`);
      if (paneState.registered) {
        await emitEnded(paneState);
      }
      state.panes.delete(paneId);
      continue;
    }

    // Capture current content
    const content = await capturePane(paneId);
    const hasChanged = hasContentChanged(paneState.lastContent, content);

    // Update state
    if (hasChanged) {
      paneState.lastContent = content;
      paneState.lastChangeTime = now;
    }

    // Check if should be stuck
    const shouldStuck = shouldBeStuck(paneState, now);

    // Emit events on state transitions
    if (!paneState.isStuck && shouldStuck) {
      console.log(`[poll] pane stuck: ${paneId} (${paneState.sessionId})`);
      paneState.isStuck = true;
      await emitStuck(paneState);
    } else if (paneState.isStuck && !shouldStuck) {
      console.log(`[poll] pane unstuck: ${paneId} (${paneState.sessionId})`);
      paneState.isStuck = false;
      await emitUnstuck(paneState);
    }
  }

  // Discover new opted-in panes
  for (const paneId of allPanes) {
    if (!state.panes.has(paneId)) {
      const title = await getPaneTitle(paneId);
      if (isOptedIn(title)) {
        const sessionId = generateSessionId(paneId, title);
        const content = await capturePane(paneId);

        console.log(`[poll] discovered opted-in pane: ${paneId} (${sessionId})`);

        const newState: PaneState = {
          paneId,
          sessionId,
          lastContent: content,
          lastChangeTime: now,
          isStuck: false,
          registered: false,
        };

        state.panes.set(paneId, newState);

        // Emit registration event
        await emitRegistered(newState);
        newState.registered = true;
      }
    }
  }
}

async function main(): Promise<void> {
  console.log("[tmux-detector] starting");
  console.log(`[tmux-detector] interval: ${POLL_INTERVAL_MS}ms`);
  console.log(`[tmux-detector] stuck threshold: ${STUCK_QUIET_MS}ms`);
  console.log(`[tmux-detector] opt-in prefix: "${OPT_IN_PREFIX}"`);
  console.log(`[tmux-detector] daemon endpoint: ${DAEMON_URL}`);

  const state: DetectorState = {
    panes: new Map(),
    lastPollTime: Date.now(),
  };

  // Main loop
  while (true) {
    await poll(state);
    await new Promise(resolve => setTimeout(resolve, POLL_INTERVAL_MS));
  }
}

// Run if executed directly
if (import.meta.main) {
  main().catch(err => {
    console.error("[tmux-detector] fatal error:", err);
    process.exit(1);
  });
}

export { main, poll, type DetectorState, type PaneState };
